<script setup>
import { onMounted, onUnmounted, ref } from 'vue';
import AppIcon from './AppIcon.vue';
const props=defineProps({api:Function,environment:Object});
const emit=defineEmits(['close','saved']);
const url=ref(''),account=ref(''),instructions=ref(''),password=ref(''),error=ref(''),busy=ref(false),loading=ref(true);
let active=true;
onMounted(async()=>{try{const data=await props.api(`admin/environments/${props.environment.id}/access`);if(active){url.value=data.access_url || `https://${props.environment.hostname}:1443`;account.value=data.access_account || '';instructions.value=data.access_instructions || '';}}catch(e){if(active)error.value=e.message;}finally{if(active)loading.value=false;}});
onUnmounted(()=>{active=false;password.value='';});
async function save(){busy.value=true;error.value='';try{await props.api(`admin/environments/${props.environment.id}/access`,{method:'POST',body:JSON.stringify({access_url:url.value,access_account:account.value,access_instructions:instructions.value,current_password:password.value})});emit('saved');}catch(e){error.value=e.message;}finally{busy.value=false;password.value='';}}
</script>
<template><section class="panel access-editor"><div class="section-heading"><div><p class="eyebrow">BÀN GIAO CHO KHÁCH HÀNG</p><h2>Thông tin truy cập · {{environment.hostname}}</h2></div><button class="icon-button" aria-label="Đóng thông tin truy cập" :disabled="busy" @click="emit('close')"><AppIcon name="close" /></button></div><p class="notice">Công bố thông tin của tài khoản đã được tạo trong NAC20. Thao tác này không tạo tài khoản hoặc thay đổi mật khẩu NAC20; không nhập mật khẩu vào ghi chú.</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="loading" role="status">Đang tải thông tin…</p><form v-else class="commerce-form" @submit.prevent="save"><label>Địa chỉ quản trị HTTPS<input v-model="url" type="url" maxlength="2048" required></label><label>Tên tài khoản NAC20 đã cấp cho khách<input v-model="account" maxlength="190" autocomplete="off" required></label><label>Hướng dẫn bàn giao, không chứa mật khẩu<textarea v-model="instructions" rows="4" maxlength="2000" placeholder="Đầu mối tiếp nhận, phạm vi quyền và cách đặt mật khẩu qua kênh riêng…"></textarea></label><label>Mật khẩu admin TN20 hiện tại<input v-model="password" type="password" autocomplete="current-password" required></label><div class="cta-row"><button class="primary" :disabled="busy">{{busy?'Đang công bố…':'Công bố cho khách hàng'}}</button><button class="secondary" type="button" :disabled="busy" @click="emit('close')">Hủy</button></div></form></section></template>
